    "code": "'use strict';\n/**\n * ============================================================================\n * Mini Relational Tuple Filter & Projection Engine (build-sql-query-interpreter)\n * ============================================================================\n * Category: Relational Foundations\n * Difficulty: Beginner (~30 min)\n * Primary Curriculum Unit: build-sql-query-interpreter\n * Related Units: why-databases-exist, tables-rows-columns-types, select-projection-aliases, where-filtering-predicates, boolean-logic-three-valued-null\n *\n * Summary:\n *   A relational tuple-at-a-time volcano iterator engine implementing Kleene three-valued logic (TRUE/FALSE/UNKNOWN), WHERE filtering, SELECT projection with expressions, ORDER BY NULLS LAST, and LIMIT/OFFSET slicing.\n *\n * Key Engineering Highlights:\n *   1. Kleene 3-valued truth table evaluation (TRUE, FALSE, UNKNOWN) for NULL-safe predicates\n *   2. Logical execution order pipeline: FROM -> WHERE -> SELECT -> DISTINCT -> ORDER BY -> LIMIT/OFFSET\n *   3. Deterministic multi-key sorting with configurable NULLS FIRST / NULLS LAST ordering\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Kleene Three-Valued Logic (3VL) Evaluator: Implement `evalComparison(left, op, right)` and `combine3VL(op, a, b)` using Kleene three-valued logic (`\"TRUE\"`, `\"FALSE\"`, `\"UNKNOWN\"`). Any standard comparison (`=`, `!=`, `<`, `>`, `<=`, `>=`) where either operand is `null` or `undefined` must return `\"UNKNOWN\"`, whereas `IS DISTINCT FROM` treats `null` as a comparable value.\n *   - Step 2: WHERE Predicate Filtering (Coercing UNKNOWN to FALSE): Implement `filterWhere(rows, predicateFn)` to evaluate a 3VL predicate across every input tuple and retain **only** rows that evaluate to `\"TRUE\"` (or boolean `true`), discarding both `\"FALSE\"` and `\"UNKNOWN\"` rows just as SQL `WHERE` clauses do.\n *   - Step 3: SELECT Projection & Derived Column Aliases: Implement `projectSelect(rows, projections, distinct = false)` to transform each input tuple into a projected tuple containing only the requested column names or computed expressions, optionally deduplicating tuples using structural serialization.\n *   - Step 4: Multi-Key ORDER BY (NULLS LAST) & LIMIT / OFFSET Slicing: Implement `orderByAndSlice(rows, orderSpecs, limit, offset)` to sort projected tuples across multiple `{ col, dir, nullsLast }` keys without mutating the source relation, then apply `offset` and `limit` window bounds.\n * ============================================================================\n */\n\nconst VAL_MAP = { TRUE: 1, UNKNOWN: 0, FALSE: -1 };\nconst REV_MAP = { '1': 'TRUE', '0': 'UNKNOWN', '-1': 'FALSE' };\n\nclass RelationalQueryEngine {\n  static evalComparison(left, op, right) {\n    const lNull = left === null || left === undefined;\n    const rNull = right === null || right === undefined;\n    if (op === 'IS DISTINCT FROM') {\n      if (lNull && rNull) return 'FALSE';\n      if (lNull || rNull) return 'TRUE';\n      return left !== right ? 'TRUE' : 'FALSE';\n    }\n    if (lNull || rNull) return 'UNKNOWN';\n    switch (op) {\n      case '=': return left === right ? 'TRUE' : 'FALSE';\n      case '!=': return left !== right ? 'TRUE' : 'FALSE';\n      case '<': return left < right ? 'TRUE' : 'FALSE';\n      case '>': return left > right ? 'TRUE' : 'FALSE';\n      case '<=': return left <= right ? 'TRUE' : 'FALSE';\n      case '>=': return left >= right ? 'TRUE' : 'FALSE';\n      default: throw new Error('Unsupported operator: ' + op);\n    }\n  }\n\n  static combine3VL(op, a, b) {\n    const va = VAL_MAP[a] ?? 0;\n    if (op === 'NOT') return REV_MAP[String(-va)];\n    const vb = VAL_MAP[b] ?? 0;\n    if (op === 'AND') return REV_MAP[String(Math.min(va, vb))];\n    if (op === 'OR') return REV_MAP[String(Math.max(va, vb))];\n    throw new Error('Unsupported logical op: ' + op);\n  }\n\n  static filterWhere(rows, predicateFn) {\n    return rows.filter(row => {\n      const res = predicateFn(row);\n      return res === true || res === 'TRUE';\n    });\n  }\n\n  static projectSelect(rows, projections, distinct = false) {\n    const projected = rows.map(row => {\n      const out = {};\n      for (const p of projections) {\n        out[p.alias] = typeof p.expr === 'function' ? p.expr(row) : row[p.expr];\n      }\n      return out;\n    });\n    if (!distinct) return projected;\n    const seen = new Set();\n    return projected.filter(r => {\n      const key = JSON.stringify(r);\n      if (seen.has(key)) return false;\n      seen.add(key);\n      return true;\n    });\n  }\n\n  static orderByAndSlice(rows, orderSpecs = [], limit = null, offset = 0) {\n    const copy = rows.slice();\n    if (orderSpecs.length > 0) {\n      copy.sort((a, b) => {\n        for (const spec of orderSpecs) {\n          const va = a[spec.col];\n          const vb = b[spec.col];\n          const aNull = va === null || va === undefined;\n          const bNull = vb === null || vb === undefined;\n          if (aNull && bNull) continue;\n          const nullsLast = spec.nullsLast !== false;\n          if (aNull) return nullsLast ? 1 : -1;\n          if (bNull) return nullsLast ? -1 : 1;\n          if (va !== vb) {\n            const cmp = va < vb ? -1 : 1;\n            return (spec.dir || 'ASC').toUpperCase() === 'DESC' ? -cmp : cmp;\n          }\n        }\n        return 0;\n      });\n    }\n    const start = Math.max(0, offset || 0);\n    return limit === null || limit === undefined ? copy.slice(start) : copy.slice(start, start + limit);\n  }\n}\n\nmodule.exports = { RelationalQueryEngine };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  assert.equal(RelationalQueryEngine.evalComparison(10, '=', 10), 'TRUE');\n  assert.equal(RelationalQueryEngine.evalComparison(null, '=', null), 'UNKNOWN');\n  assert.equal(RelationalQueryEngine.evalComparison(null, 'IS DISTINCT FROM', null), 'FALSE');\n  assert.equal(RelationalQueryEngine.evalComparison(null, 'IS DISTINCT FROM', 5), 'TRUE');\n  assert.equal(RelationalQueryEngine.combine3VL('AND', 'UNKNOWN', 'FALSE'), 'FALSE');\n  assert.equal(RelationalQueryEngine.combine3VL('OR', 'UNKNOWN', 'TRUE'), 'TRUE');\n  assert.equal(RelationalQueryEngine.combine3VL('NOT', 'UNKNOWN'), 'UNKNOWN');\n\n  const data = [\n    { id: 1, dept: 'Eng', salary: 120, bonus: 20 },\n    { id: 2, dept: 'Eng', salary: 150, bonus: null },\n    { id: 3, dept: 'Sales', salary: 110, bonus: 15 },\n    { id: 4, dept: 'Eng', salary: 120, bonus: 20 }\n  ];\n  const filtered = RelationalQueryEngine.filterWhere(data, r =>\n    RelationalQueryEngine.evalComparison(r.bonus, '>', 10)\n  );\n  assert.equal(filtered.length, 3);\n\n  const proj = RelationalQueryEngine.projectSelect(filtered, [\n    { alias: 'dept', expr: 'dept' },\n    { alias: 'comp', expr: r => r.salary + (r.bonus || 0) }\n  ], true);\n  assert.equal(proj.length, 2);\n\n  const sorted = RelationalQueryEngine.orderByAndSlice(data, [\n    { col: 'bonus', dir: 'DESC', nullsLast: true },\n    { col: 'id', dir: 'ASC' }\n  ], 3, 1);\n  assert.deepEqual(sorted.map(r => r.id), [4, 3, 2]);\n  return true;\n}\nrunTests();\n",
