    "code": "'use strict';\n/**\n * ============================================================================\n * Multi-Dimensional Revenue, Cohort & Funnel Aggregation Suite (build-executive-kpi-aggregation-suite)\n * ============================================================================\n * Category: Aggregation & Grouping Sets\n * Difficulty: Intermediate (~35 min)\n * Primary Curriculum Unit: build-executive-kpi-aggregation-suite\n * Related Units: aggregate-functions-internals, group-by-execution-mechanics, having-vs-where-pipeline, conditional-aggregation-filter, string-json-array-aggregation\n *\n * Summary:\n *   A single-pass multi-dimensional OLAP aggregation engine implementing conditional FILTER (WHERE ...), GROUPING SETS / ROLLUP subtotals with bitmask GROUPING() flags, and exact/interpolated percentiles.\n *\n * Key Engineering Highlights:\n *   1. Single-pass conditional aggregation equivalent to COUNT/SUM(...) FILTER (WHERE ...)\n *   2. Hierarchical ROLLUP and GROUPING SETS generator with bitmask GROUPING(col) metadata\n *   3. Exact discrete (PERCENTILE_DISC) and continuous interpolated (PERCENTILE_CONT) quantiles\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Single-Pass Conditional Aggregation (FILTER Clause): Implement `conditionalAggregate(orders, groupCol)` to compute `total_orders`, `paid_orders`, `paid_revenue_cents`, and `refunded_revenue_cents` per group in a single table scan without self-joins.\n *   - Step 2: Hierarchical ROLLUP & Bitmask GROUPING() Indicator: Implement `rollupRevenue(orders, dim1, dim2)` to compute hierarchical subtotals across `(dim1, dim2)`, `(dim1, null)`, and the grand total `(null, null)`, setting `grouping_id` (`0`, `1`, or `3`) to distinguish real `NULL` keys from rollup super-aggregates.\n *   - Step 3: Continuous Linear-Interpolated Percentile (PERCENTILE_CONT): Implement `percentileCont(values, p)` to ignore `null`/`undefined` inputs, sort the remaining numeric values, and linearly interpolate at fractional index `pos = p * (n - 1)`.\n *   - Step 4: HAVING Post-Aggregation Group Filter: Implement `filterHaving(groups, minPaidRevenueCents, minConversionRate)` to retain only groups meeting post-aggregation business thresholds.\n * ============================================================================\n */\n\nclass OlapAggregationSuite {\n  static conditionalAggregate(orders, groupCol) {\n    const groups = new Map();\n    for (const o of orders) {\n      const k = o[groupCol];\n      let g = groups.get(k);\n      if (!g) {\n        g = { [groupCol]: k, total_orders: 0, paid_orders: 0, paid_revenue_cents: 0, refunded_revenue_cents: 0 };\n        groups.set(k, g);\n      }\n      g.total_orders += 1;\n      if (o.status === 'paid') {\n        g.paid_orders += 1;\n        g.paid_revenue_cents += o.amount_cents || 0;\n      } else if (o.status === 'refunded') {\n        g.refunded_revenue_cents += o.amount_cents || 0;\n      }\n    }\n    return Array.from(groups.values());\n  }\n\n  static rollupRevenue(orders, dim1, dim2) {\n    const levels = [\n      { mask: 0, keyFn: o => `${o[dim1]}|${o[dim2]}`, d1: o => o[dim1], d2: o => o[dim2] },\n      { mask: 1, keyFn: o => `${o[dim1]}|*`, d1: o => o[dim1], d2: () => null },\n      { mask: 3, keyFn: () => '*|*', d1: () => null, d2: () => null }\n    ];\n    const out = [];\n    for (const lvl of levels) {\n      const map = new Map();\n      for (const o of orders) {\n        const k = lvl.keyFn(o);\n        let row = map.get(k);\n        if (!row) {\n          row = { [dim1]: lvl.d1(o), [dim2]: lvl.d2(o), grouping_id: lvl.mask, revenue_cents: 0 };\n          map.set(k, row);\n        }\n        row.revenue_cents += o.amount_cents || 0;\n      }\n      out.push(...map.values());\n    }\n    return out;\n  }\n\n  static percentileCont(values, p) {\n    const clean = values.filter(v => v !== null && v !== undefined && !Number.isNaN(v)).sort((a, b) => a - b);\n    if (clean.length === 0) return null;\n    const pos = p * (clean.length - 1);\n    const lo = Math.floor(pos);\n    const hi = Math.ceil(pos);\n    const frac = pos - lo;\n    return clean[lo] + frac * (clean[hi] - clean[lo]);\n  }\n\n  static filterHaving(groups, minPaidRevenueCents, minConversionRate) {\n    return groups.filter(g => {\n      const rate = g.total_orders > 0 ? g.paid_orders / g.total_orders : 0;\n      return g.paid_revenue_cents >= minPaidRevenueCents && rate >= minConversionRate;\n    });\n  }\n}\n\nmodule.exports = { OlapAggregationSuite };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const orders = [\n    { region: 'US', plan: 'Pro', status: 'paid', amount_cents: 1000 },\n    { region: 'US', plan: 'Pro', status: 'refunded', amount_cents: 500 },\n    { region: 'US', plan: 'Enterprise', status: 'paid', amount_cents: 4000 },\n    { region: 'EU', plan: 'Pro', status: 'paid', amount_cents: 800 }\n  ];\n\n  const cond = OlapAggregationSuite.conditionalAggregate(orders, 'region');\n  const us = cond.find(r => r.region === 'US');\n  assert.equal(us.total_orders, 3);\n  assert.equal(us.paid_orders, 2);\n  assert.equal(us.paid_revenue_cents, 5000);\n  assert.equal(us.refunded_revenue_cents, 500);\n\n  const rollup = OlapAggregationSuite.rollupRevenue(orders, 'region', 'plan');\n  const grand = rollup.find(r => r.grouping_id === 3);\n  assert.equal(grand.revenue_cents, 6300);\n\n  assert.equal(OlapAggregationSuite.percentileCont([10, 20, null, 30, 40], 0.5), 25);\n  const having = OlapAggregationSuite.filterHaving(cond, 2000, 0.5);\n  assert.equal(having.length, 1);\n  assert.equal(having[0].region, 'US');\n  return true;\n}\nrunTests();\n",
