    "code": "'use strict';\n/**\n * ============================================================================\n * Bill-of-Materials & Social Graph Reachability Engine (build-hierarchical-graph-query-engine)\n * ============================================================================\n * Category: Subqueries, CTEs & Recursion\n * Difficulty: Advanced (~40 min)\n * Primary Curriculum Unit: build-hierarchical-graph-query-engine\n * Related Units: scalar-row-table-subqueries, correlated-subqueries-mechanics, exists-not-exists-null-safety, lateral-joins-cross-apply, common-table-expressions-with\n *\n * Summary:\n *   A fixed-point recursive CTE execution engine supporting working-table iteration, UNION vs UNION ALL deduplication, path-array cycle detection, Bill-of-Materials cost rollup, and NULL-safe NOT EXISTS anti-joins.\n *\n * Key Engineering Highlights:\n *   1. Fixed-point iterative working-table evaluation matching SQL WITH RECURSIVE semantics\n *   2. Path-vector cycle detection preventing infinite loops on cyclic dependency graphs\n *   3. Bill-of-Materials component multiplication and NULL-safe NOT EXISTS anti-join evaluation\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Fixed-Point WITH RECURSIVE Iterator with Cycle Detection: Implement `traverseHierarchy(edges, rootId, maxDepth)` using SQL `WITH RECURSIVE` working-table semantics. Track `path: [...parent.path, childId]` on every tuple and skip any edge where `parent.path.includes(childId)` to prevent infinite recursion on cyclic graphs.\n *   - Step 2: Bill-of-Materials (BOM) Multiplicative Quantity & Cost Rollup: Implement `computeBomCost(bomEdges, unitCosts, rootPartId)` to recursively expand sub-assemblies, multiplying component quantities along each root-to-leaf path and summing total unit costs.\n *   - Step 3: NULL-Safe NOT EXISTS Anti-Join vs NOT IN Trap: Implement `notExistsAntiJoin(outerRows, innerRows, key)` so that `null` values in `innerRows` never poison the anti-join result (unlike `NOT IN`).\n *   - Step 4: Correlated LATERAL Top-K Per Parent Node: Implement `lateralTopK(parents, children, fkCol, metricCol, k)` to execute a correlated top-$k$ subquery for each parent row.\n * ============================================================================\n */\n\nclass RecursiveGraphEngine {\n  static traverseHierarchy(edges, rootId, maxDepth = 10) {\n    const result = [{ id: rootId, parent_id: null, depth: 0, path: [rootId] }];\n    let working = result.slice();\n\n    while (working.length > 0) {\n      const nextWorking = [];\n      for (const cur of working) {\n        if (cur.depth >= maxDepth) continue;\n        for (const e of edges) {\n          if (e.parent_id === cur.id && !cur.path.includes(e.child_id)) {\n            const tuple = {\n              id: e.child_id,\n              parent_id: cur.id,\n              depth: cur.depth + 1,\n              path: [...cur.path, e.child_id]\n            };\n            nextWorking.push(tuple);\n            result.push(tuple);\n          }\n        }\n      }\n      working = nextWorking;\n    }\n    return result;\n  }\n\n  static computeBomCost(bomEdges, unitCosts, rootPartId) {\n    let working = [{ part_id: rootPartId, qty: 1, path: [rootPartId] }];\n    let totalCost = 0;\n\n    while (working.length > 0) {\n      const next = [];\n      for (const item of working) {\n        const subParts = bomEdges.filter(e => e.parent_part === item.part_id);\n        if (subParts.length === 0) {\n          totalCost += item.qty * (unitCosts[item.part_id] || 0);\n        } else {\n          for (const sub of subParts) {\n            if (!item.path.includes(sub.child_part)) {\n              next.push({\n                part_id: sub.child_part,\n                qty: item.qty * sub.qty,\n                path: [...item.path, sub.child_part]\n              });\n            }\n          }\n        }\n      }\n      working = next;\n    }\n    return totalCost;\n  }\n\n  static notExistsAntiJoin(outerRows, innerRows, key) {\n    return outerRows.filter(out =>\n      !innerRows.some(inn => inn[key] !== null && inn[key] !== undefined && inn[key] === out[key])\n    );\n  }\n\n  static lateralTopK(parents, children, fkCol, metricCol, k = 2) {\n    const out = [];\n    for (const p of parents) {\n      const top = children\n        .filter(c => c[fkCol] === p.id)\n        .sort((a, b) => b[metricCol] - a[metricCol])\n        .slice(0, k);\n      for (const c of top) {\n        out.push({ parent_id: p.id, child_id: c.id, [metricCol]: c[metricCol] });\n      }\n    }\n    return out;\n  }\n}\n\nmodule.exports = { RecursiveGraphEngine };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const edges = [\n    { parent_id: 1, child_id: 2 },\n    { parent_id: 2, child_id: 3 },\n    { parent_id: 3, child_id: 1 }, // cycle back to root!\n    { parent_id: 2, child_id: 4 }\n  ];\n  const tree = RecursiveGraphEngine.traverseHierarchy(edges, 1, 10);\n  assert.deepEqual(tree.map(n => n.id), [1, 2, 3, 4]);\n\n  const bom = [\n    { parent_part: 'BIKE', child_part: 'WHEEL', qty: 2 },\n    { parent_part: 'BIKE', child_part: 'FRAME', qty: 1 },\n    { parent_part: 'WHEEL', child_part: 'SPOKE', qty: 30 },\n    { parent_part: 'WHEEL', child_part: 'RIM', qty: 1 }\n  ];\n  const costs = { SPOKE: 1, RIM: 20, FRAME: 100 };\n  assert.equal(RecursiveGraphEngine.computeBomCost(bom, costs, 'BIKE'), 2 * (30 * 1 + 20) + 100);\n\n  const anti = RecursiveGraphEngine.notExistsAntiJoin(\n    [{ id: 1 }, { id: 2 }, { id: 3 }],\n    [{ id: 1 }, { id: null }],\n    'id'\n  );\n  assert.deepEqual(anti.map(r => r.id), [2, 3]);\n\n  const lat = RecursiveGraphEngine.lateralTopK(\n    [{ id: 10 }, { id: 20 }],\n    [\n      { id: 1, dept_id: 10, salary: 100 },\n      { id: 2, dept_id: 10, salary: 300 },\n      { id: 3, dept_id: 10, salary: 200 },\n      { id: 4, dept_id: 20, salary: 150 }\n    ],\n    'dept_id',\n    'salary',\n    2\n  );\n  assert.deepEqual(lat.map(r => r.child_id), [2, 3, 4]);\n  return true;\n}\nrunTests();\n",
