    "code": "'use strict';\n/**\n * ============================================================================\n * Clickstream Sessionizer, Streak Tracker & Rolling Window Analyzer (build-sessionization-retention-engine)\n * ============================================================================\n * Category: Window Functions & Analytics\n * Difficulty: Advanced (~40 min)\n * Primary Curriculum Unit: build-sessionization-retention-engine\n * Related Units: window-functions-mental-model, partition-by-order-by-mechanics, ranking-functions-row-number-rank, top-n-per-group-deduplication, offset-functions-lag-lead-first-last\n *\n * Summary:\n *   An analytical window function engine implementing LAG()-based clickstream sessionization, ROW_NUMBER() date-difference islands for consecutive activity streaks, and ROWS vs RANGE sliding window frames.\n *\n * Key Engineering Highlights:\n *   1. Clickstream sessionization via LAG(ts) inactivity threshold detection and cumulative SUM() session IDs\n *   2. Gaps-and-Islands streak length calculation using the date - ROW_NUMBER() constant-difference invariant\n *   3. Exact physical ROWS vs logical value-based RANGE window frame evaluation with peer grouping\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Clickstream Sessionization via LAG() & Cumulative Sum: Implement `sessionizeEvents(events, timeoutSec)` to partition events by `user_id`, order by `tsSec`, compute `LAG(tsSec)`, flag new sessions whenever `tsSec - prevTs > timeoutSec`, and assign a running `session_id` via cumulative sum.\n *   - Step 2: Gaps-and-Islands Consecutive Day Streak Finder: Implement `computeStreaks(activityDays)` using the classic Gaps-and-Islands invariant: subtracting sequential `ROW_NUMBER()` from integer `dayIndex` yields a constant `islandKey` across consecutive days.\n *   - Step 3: Physical ROWS Window Frame Moving Average: Implement `movingAvgRows(rows, metricCol, precedingRows)` to compute the physical row-count sliding window average.\n *   - Step 4: Logical RANGE Window Frame Sum with Peer Ties: Implement `movingSumRange(rows, orderCol, metricCol, delta)` to sum all tuples whose `orderCol` falls within `[curOrder - delta, curOrder]`, including all duplicate peer timestamps.\n * ============================================================================\n */\n\nclass WindowAnalyticsEngine {\n  static sessionizeEvents(events, timeoutSec = 1800) {\n    const sorted = events.slice().sort((a, b) =>\n      a.user_id !== b.user_id ? a.user_id - b.user_id : a.tsSec - b.tsSec\n    );\n    const out = [];\n    let prevUser = null;\n    let prevTs = null;\n    let sessionNum = 0;\n\n    for (const ev of sorted) {\n      if (ev.user_id !== prevUser) {\n        prevUser = ev.user_id;\n        prevTs = null;\n        sessionNum = 0;\n      }\n      const isNew = prevTs === null || (ev.tsSec - prevTs) > timeoutSec ? 1 : 0;\n      sessionNum += isNew;\n      prevTs = ev.tsSec;\n      out.push({ ...ev, is_new_session: isNew, session_num: sessionNum });\n    }\n    return out;\n  }\n\n  static computeStreaks(activityDays) {\n    const byUser = new Map();\n    for (const r of activityDays) {\n      if (!byUser.has(r.user_id)) byUser.set(r.user_id, new Set());\n      byUser.get(r.user_id).add(r.dayIndex);\n    }\n    const streaks = [];\n    for (const [user_id, daySet] of byUser.entries()) {\n      const days = Array.from(daySet).sort((a, b) => a - b);\n      const islands = new Map();\n      days.forEach((dayIndex, idx) => {\n        const rn = idx + 1;\n        const islandKey = dayIndex - rn;\n        if (!islands.has(islandKey)) {\n          islands.set(islandKey, { user_id, startDay: dayIndex, endDay: dayIndex, length: 0 });\n        }\n        const isl = islands.get(islandKey);\n        isl.endDay = dayIndex;\n        isl.length += 1;\n      });\n      streaks.push(...islands.values());\n    }\n    return streaks;\n  }\n\n  static movingAvgRows(rows, metricCol, precedingRows = 2) {\n    return rows.map((r, i) => {\n      const start = Math.max(0, i - precedingRows);\n      let sum = 0;\n      let count = 0;\n      for (let j = start; j <= i; j++) {\n        sum += rows[j][metricCol];\n        count += 1;\n      }\n      return { ...r, moving_avg: sum / count };\n    });\n  }\n\n  static movingSumRange(rows, orderCol, metricCol, delta) {\n    const sorted = rows.slice().sort((a, b) => a[orderCol] - b[orderCol]);\n    return sorted.map(r => {\n      const curVal = r[orderCol];\n      let sum = 0;\n      for (const peer of sorted) {\n        if (peer[orderCol] >= curVal - delta && peer[orderCol] <= curVal) {\n          sum += peer[metricCol];\n        }\n      }\n      return { ...r, range_sum: sum };\n    });\n  }\n}\n\nmodule.exports = { WindowAnalyticsEngine };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const events = [\n    { user_id: 1, tsSec: 100 },\n    { user_id: 1, tsSec: 500 },\n    { user_id: 1, tsSec: 3000 },\n    { user_id: 2, tsSec: 200 }\n  ];\n  const sess = WindowAnalyticsEngine.sessionizeEvents(events, 1800);\n  assert.deepEqual(sess.map(s => s.session_num), [1, 1, 2, 1]);\n\n  const streaks = WindowAnalyticsEngine.computeStreaks([\n    { user_id: 1, dayIndex: 1 },\n    { user_id: 1, dayIndex: 2 },\n    { user_id: 1, dayIndex: 2 }, // duplicate same-day login\n    { user_id: 1, dayIndex: 3 },\n    { user_id: 1, dayIndex: 6 },\n    { user_id: 1, dayIndex: 7 }\n  ]);\n  assert.equal(streaks.length, 2);\n  assert.equal(streaks[0].length, 3);\n  assert.equal(streaks[1].length, 2);\n\n  const series = [\n    { day: 1, val: 10 },\n    { day: 1, val: 20 }, // peer tie on day=1\n    { day: 2, val: 30 }\n  ];\n  const rowsAvg = WindowAnalyticsEngine.movingAvgRows(series, 'val', 1);\n  assert.equal(rowsAvg[0].moving_avg, 10);\n  assert.equal(rowsAvg[1].moving_avg, 15);\n\n  const rangeSum = WindowAnalyticsEngine.movingSumRange(series, 'day', 'val', 0);\n  assert.equal(rangeSum[0].range_sum, 30); // RANGE includes both day=1 peers!\n  return true;\n}\nrunTests();\n",
