    "code": "'use strict';\n/**\n * ============================================================================\n * Normalize a Legacy Flat Spreadsheet into a 3NF/BCNF System (build-normalized-booking-schema)\n * ============================================================================\n * Category: Relational Schema Design & Normalization\n * Difficulty: Advanced (~40 min)\n * Primary Curriculum Unit: build-normalized-booking-schema\n * Related Units: entity-relationship-modeling, functional-dependencies-keys, first-normal-form-atomicity, second-third-normal-form, boyce-codd-fourth-fifth-normal-form\n *\n * Summary:\n *   An algorithmic functional dependency analyzer implementing Armstrong’s Axiom attribute closure X+, candidate key discovery, BCNF violation detection, and lossless-join decomposition.\n *\n * Key Engineering Highlights:\n *   1. Attribute closure X+ fixed-point computation via Armstrong’s Axioms\n *   2. Minimal superkey / candidate key synthesis over arbitrary functional dependency sets\n *   3. Automated BCNF violation detector and lossless-join relation decomposition\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Attribute Closure (X+) via Armstrong’s Reflexivity & Transitivity: Implement `attributeClosure(attrs, fds)` to compute the attribute closure $X^+$ of an attribute set `attrs` under a set of functional dependencies `fds = [{ left: [...], right: [...] }]`.\n *   - Step 2: Superkey & Candidate Key Verification: Implement `isSuperkey(allAttrs, candidateAttrs, fds)` by testing whether the attribute closure of `candidateAttrs` equals the universal attribute set `allAttrs`.\n *   - Step 3: BCNF Violation Detector: Implement `findBcnfViolations(allAttrs, fds)` to return every non-trivial functional dependency $X \\to Y$ whose determinant $X$ is not a superkey of `allAttrs`.\n *   - Step 4: Lossless-Join BCNF Decomposition & Flat-Row Projection: Implement `decomposeBcnfStep(allAttrs, violatingFd, fds)` to perform one lossless-join BCNF split into `{ r1, r2 }` and project a flat spreadsheet dataset into deduplicated normalized relations.\n * ============================================================================\n */\n\nclass NormalizationEngine {\n  static attributeClosure(attrs, fds) {\n    const closure = new Set(attrs);\n    let changed = true;\n    while (changed) {\n      changed = false;\n      for (const fd of fds) {\n        if (fd.left.every(a => closure.has(a))) {\n          for (const b of fd.right) {\n            if (!closure.has(b)) {\n              closure.add(b);\n              changed = true;\n            }\n          }\n        }\n      }\n    }\n    return Array.from(closure).sort();\n  }\n\n  static isSuperkey(allAttrs, candidateAttrs, fds) {\n    const closure = new Set(this.attributeClosure(candidateAttrs, fds));\n    return allAttrs.every(a => closure.has(a));\n  }\n\n  static findBcnfViolations(allAttrs, fds) {\n    return fds.filter(fd => {\n      const nonTrivialRight = fd.right.filter(r => !fd.left.includes(r));\n      if (nonTrivialRight.length === 0) return false;\n      return !this.isSuperkey(allAttrs, fd.left, fds);\n    });\n  }\n\n  static decomposeBcnfStep(allAttrs, violatingFd, fds) {\n    const xPlus = this.attributeClosure(violatingFd.left, fds);\n    const leftSet = new Set(violatingFd.left);\n    const xPlusMinusX = new Set(xPlus.filter(a => !leftSet.has(a)));\n    const r1 = xPlus;\n    const r2 = allAttrs.filter(a => !xPlusMinusX.has(a)).sort();\n    return { r1, r2 };\n  }\n}\n\nmodule.exports = { NormalizationEngine };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const allAttrs = ['booking_id', 'room_id', 'building', 'guest_id', 'guest_email'];\n  const fds = [\n    { left: ['booking_id'], right: ['room_id', 'guest_id'] },\n    { left: ['room_id'], right: ['building'] },\n    { left: ['guest_id'], right: ['guest_email'] }\n  ];\n\n  const closure = NormalizationEngine.attributeClosure(['booking_id'], fds);\n  assert.deepEqual(closure, ['booking_id', 'building', 'guest_email', 'guest_id', 'room_id']);\n  assert.equal(NormalizationEngine.isSuperkey(allAttrs, ['booking_id'], fds), true);\n  assert.equal(NormalizationEngine.isSuperkey(allAttrs, ['room_id'], fds), false);\n\n  const violations = NormalizationEngine.findBcnfViolations(allAttrs, fds);\n  assert.equal(violations.length, 2);\n\n  const split = NormalizationEngine.decomposeBcnfStep(allAttrs, { left: ['room_id'], right: ['building'] }, fds);\n  assert.deepEqual(split.r1, ['building', 'room_id']);\n  assert.deepEqual(split.r2, ['booking_id', 'guest_email', 'guest_id', 'room_id']);\n  return true;\n}\nrunTests();\n",
