    "code": "'use strict';\n/**\n * ============================================================================\n * Star Schema with Automated SCD Type 2 Dimension Pipeline (build-scd-type2-warehouse-pipeline)\n * ============================================================================\n * Category: Dimensional Modeling & Kimball OLAP\n * Difficulty: Advanced (~40 min)\n * Primary Curriculum Unit: build-scd-type2-warehouse-pipeline\n * Related Units: oltp-vs-olap-workload-physics, star-schema-facts-dimensions, snowflake-vs-star-vs-obt, slowly-changing-dimensions-scd, bridge-tables-junk-role-dimensions\n *\n * Summary:\n *   A Kimball dimensional warehouse pipeline implementing automated Slowly Changing Dimension (SCD Type 2) effective date range versioning, surrogate key assignment, and point-in-time historical fact-to-dimension joins.\n *\n * Key Engineering Highlights:\n *   1. Automated SCD Type 2 change detection expiring prior version rows and inserting new surrogate keys\n *   2. Half-open [valid_from, valid_to) temporal interval invariants with is_current boolean flags\n *   3. As-was point-in-time historical fact table enrichment resolving surrogate keys by event timestamp\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Initial Dimension Seed & Surrogate Key Allocation: Implement the initial insert path in `applyChange(naturalKey, attrs, changeTs)` to allocate a monotonically increasing `sk` (surrogate key) and initialize `[valid_from, \"9999-12-31\")` with `is_current: true`.\n *   - Step 2: SCD Type 2 Attribute Diffing & Prior Row Expiration: Complete `applyChange(naturalKey, attrs, changeTs)` so that when tracked attributes change, the existing current version is expired (`valid_to = changeTs`, `is_current = false`) and a new current version is appended; if attributes are unchanged, perform a no-op.\n *   - Step 3: Point-in-Time Historical Surrogate Key Lookup: Implement `lookupSurrogateKeyAsOf(naturalKey, eventTs)` using half-open interval logic (`valid_from <= eventTs && eventTs < valid_to`) so boundary timestamps match exactly one version.\n *   - Step 4: As-Was Historical Fact Table Star Join & Aggregation: Implement `enrichAndAggregateFacts(facts)` to join each fact event to the dimension version that was active at `fact.eventTs` and aggregate revenue by historical tier.\n * ============================================================================\n */\n\nclass ScdType2Pipeline {\n  constructor() {\n    this.nextSk = 1;\n    this.dimRows = [];\n  }\n\n  applyChange(naturalKey, attrs, changeTs) {\n    const current = this.dimRows.find(r => r.naturalKey === naturalKey && r.is_current);\n    if (!current) {\n      const row = {\n        sk: this.nextSk++,\n        naturalKey,\n        ...attrs,\n        valid_from: changeTs,\n        valid_to: '9999-12-31',\n        is_current: true\n      };\n      this.dimRows.push(row);\n      return row;\n    }\n\n    const changed = Object.keys(attrs).some(k => current[k] !== attrs[k]);\n    if (!changed) return current;\n\n    current.valid_to = changeTs;\n    current.is_current = false;\n\n    const nextRow = {\n      sk: this.nextSk++,\n      naturalKey,\n      ...attrs,\n      valid_from: changeTs,\n      valid_to: '9999-12-31',\n      is_current: true\n    };\n    this.dimRows.push(nextRow);\n    return nextRow;\n  }\n\n  lookupSurrogateKeyAsOf(naturalKey, eventTs) {\n    return this.dimRows.find(\n      r => r.naturalKey === naturalKey && r.valid_from <= eventTs && eventTs < r.valid_to\n    ) || null;\n  }\n\n  enrichAndAggregateFacts(facts) {\n    const totalsByTier = {};\n    for (const f of facts) {\n      const dim = this.lookupSurrogateKeyAsOf(f.naturalKey, f.eventTs);\n      const tier = dim ? dim.tier : 'UNKNOWN';\n      totalsByTier[tier] = (totalsByTier[tier] || 0) + f.amount_cents;\n    }\n    return totalsByTier;\n  }\n}\n\nmodule.exports = { ScdType2Pipeline };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const scd = new ScdType2Pipeline();\n  scd.applyChange('cust_1', { tier: 'Free' }, '2025-01-01');\n  scd.applyChange('cust_1', { tier: 'Free' }, '2025-02-01'); // idempotent no-op\n  assert.equal(scd.dimRows.length, 1);\n\n  scd.applyChange('cust_1', { tier: 'Pro' }, '2025-03-01');\n  scd.applyChange('cust_1', { tier: 'Enterprise' }, '2025-06-01');\n  assert.equal(scd.dimRows.length, 3);\n\n  assert.equal(scd.lookupSurrogateKeyAsOf('cust_1', '2025-02-15').tier, 'Free');\n  assert.equal(scd.lookupSurrogateKeyAsOf('cust_1', '2025-03-01').tier, 'Pro'); // half-open boundary!\n  assert.equal(scd.lookupSurrogateKeyAsOf('cust_1', '2025-07-10').tier, 'Enterprise');\n\n  const agg = scd.enrichAndAggregateFacts([\n    { naturalKey: 'cust_1', eventTs: '2025-01-15', amount_cents: 100 },\n    { naturalKey: 'cust_1', eventTs: '2025-04-10', amount_cents: 500 },\n    { naturalKey: 'cust_1', eventTs: '2025-08-01', amount_cents: 2000 }\n  ]);\n  assert.deepEqual(agg, { Free: 100, Pro: 500, Enterprise: 2000 });\n  return true;\n}\nrunTests();\n",
