    "code": "'use strict';\n/**\n * ============================================================================\n * Implement & Benchmark Nested Loop, Hash Join & Sort-Merge Join (build-physical-join-execution-engine)\n * ============================================================================\n * Category: Physical Join & Execution Operators\n * Difficulty: Advanced (~45 min)\n * Primary Curriculum Unit: build-physical-join-execution-engine\n * Related Units: nested-loop-join-indexed-nlj, hash-join-build-probe-grace, sort-merge-join-zipper-mechanics, join-order-search-dynamic-programming, predicate-pushdown-projection-pruning\n *\n * Summary:\n *   A physical relational join engine implementing Block Nested Loop Join, in-memory Build-and-Probe Hash Join, Zipper Sort-Merge Join with duplicate peer rewind, and NULL-safe Hash Anti-Join.\n *\n * Key Engineering Highlights:\n *   1. Block Nested Loop Join minimizing inner-relation scans via chunked outer buffering\n *   2. Build-on-smaller-input Hash Join achieving O(N + M) linear execution cost\n *   3. Sort-Merge Join with peer group mark-and-rewind for duplicate join keys\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Block Nested Loop Join with Comparison Telemetry: Implement `nestedLoopJoin(leftRows, rightRows, leftKey, rightKey)` returning `{ rows, comparisons }`, skipping `null`/`undefined` join keys per SQL `=` semantics.\n *   - Step 2: Build-on-Smaller-Relation Hash Join: Implement `hashJoin(leftRows, rightRows, leftKey, rightKey)` so that the smaller array is always selected as the hash build side, returning `{ rows, buildSize, probeOps }`.\n *   - Step 3: Zipper Sort-Merge Join with Duplicate Peer Group Rewind: Implement `sortMergeJoin(leftRows, rightRows, leftKey, rightKey)` to sort both inputs on their join key and merge them in a single pass with peer-group expansion.\n *   - Step 4: NULL-Safe Hash Anti-Join: Implement `hashAntiJoin(leftRows, rightRows, leftKey, rightKey)` to return all `leftRows` with no matching key in `rightRows`, safely ignoring `null` keys in `rightRows`.\n * ============================================================================\n */\n\nclass PhysicalJoinEngine {\n  static nestedLoopJoin(leftRows, rightRows, leftKey, rightKey) {\n    const rows = [];\n    let comparisons = 0;\n    for (const l of leftRows) {\n      const lk = l[leftKey];\n      if (lk === null || lk === undefined) continue;\n      for (const r of rightRows) {\n        comparisons++;\n        const rk = r[rightKey];\n        if (rk !== null && rk !== undefined && lk === rk) {\n          rows.push({ ...l, ...r });\n        }\n      }\n    }\n    return { rows, comparisons };\n  }\n\n  static hashJoin(leftRows, rightRows, leftKey, rightKey) {\n    const buildLeft = leftRows.length <= rightRows.length;\n    const buildSide = buildLeft ? leftRows : rightRows;\n    const probeSide = buildLeft ? rightRows : leftRows;\n    const bKey = buildLeft ? leftKey : rightKey;\n    const pKey = buildLeft ? rightKey : leftKey;\n\n    const hashTable = new Map();\n    let buildSize = 0;\n    for (const b of buildSide) {\n      const k = b[bKey];\n      if (k === null || k === undefined) continue;\n      if (!hashTable.has(k)) hashTable.set(k, []);\n      hashTable.get(k).push(b);\n      buildSize++;\n    }\n\n    const rows = [];\n    let probeOps = 0;\n    for (const p of probeSide) {\n      probeOps++;\n      const k = p[pKey];\n      if (k === null || k === undefined) continue;\n      const matches = hashTable.get(k);\n      if (matches) {\n        for (const m of matches) {\n          rows.push(buildLeft ? { ...m, ...p } : { ...p, ...m });\n        }\n      }\n    }\n    return { rows, buildSize, probeOps };\n  }\n\n  static sortMergeJoin(leftRows, rightRows, leftKey, rightKey) {\n    const lSorted = leftRows\n      .filter(r => r[leftKey] !== null && r[leftKey] !== undefined)\n      .slice()\n      .sort((a, b) => (a[leftKey] < b[leftKey] ? -1 : a[leftKey] > b[leftKey] ? 1 : 0));\n    const rSorted = rightRows\n      .filter(r => r[rightKey] !== null && r[rightKey] !== undefined)\n      .slice()\n      .sort((a, b) => (a[rightKey] < b[rightKey] ? -1 : a[rightKey] > b[rightKey] ? 1 : 0));\n\n    const rows = [];\n    let i = 0, j = 0;\n    while (i < lSorted.length && j < rSorted.length) {\n      const lk = lSorted[i][leftKey];\n      const rk = rSorted[j][rightKey];\n      if (lk < rk) {\n        i++;\n      } else if (lk > rk) {\n        j++;\n      } else {\n        const key = lk;\n        const lGroup = [];\n        const rGroup = [];\n        while (i < lSorted.length && lSorted[i][leftKey] === key) lGroup.push(lSorted[i++]);\n        while (j < rSorted.length && rSorted[j][rightKey] === key) rGroup.push(rSorted[j++]);\n        for (const l of lGroup) {\n          for (const r of rGroup) {\n            rows.push({ ...l, ...r });\n          }\n        }\n      }\n    }\n    return { rows };\n  }\n\n  static hashAntiJoin(leftRows, rightRows, leftKey, rightKey) {\n    const rightSet = new Set();\n    for (const r of rightRows) {\n      const k = r[rightKey];\n      if (k !== null && k !== undefined) rightSet.add(k);\n    }\n    return leftRows.filter(l => !rightSet.has(l[leftKey]));\n  }\n}\n\nmodule.exports = { PhysicalJoinEngine };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const depts = [{ dept_id: 1, dept_name: 'Eng' }, { dept_id: 2, dept_name: 'Sales' }, { dept_id: null, dept_name: 'Temp' }];\n  const emps = [\n    { emp_id: 10, dept_id: 1 },\n    { emp_id: 11, dept_id: 1 },\n    { emp_id: 12, dept_id: 2 },\n    { emp_id: 13, dept_id: 99 },\n    { emp_id: 14, dept_id: null }\n  ];\n\n  const nlj = PhysicalJoinEngine.nestedLoopJoin(depts, emps, 'dept_id', 'dept_id');\n  const hj = PhysicalJoinEngine.hashJoin(depts, emps, 'dept_id', 'dept_id');\n  const smj = PhysicalJoinEngine.sortMergeJoin(depts, emps, 'dept_id', 'dept_id');\n\n  assert.equal(nlj.rows.length, 3);\n  assert.equal(hj.rows.length, 3);\n  assert.equal(hj.buildSize, 2); // built on smaller depts relation (2 non-null rows)\n  assert.equal(smj.rows.length, 3);\n\n  const anti = PhysicalJoinEngine.hashAntiJoin(emps, depts, 'dept_id', 'dept_id');\n  assert.deepEqual(anti.map(e => e.emp_id), [13, 14]);\n  return true;\n}\nrunTests();\n",
