    "code": "'use strict';\n/**\n * ============================================================================\n * Dual-Session Concurrency Anomaly & Isolation Verifier (build-transaction-anomaly-simulator)\n * ============================================================================\n * Category: Transactions, Isolation & Concurrency\n * Difficulty: Advanced (~40 min)\n * Primary Curriculum Unit: build-transaction-anomaly-simulator\n * Related Units: acid-properties-under-the-hood, transaction-lifecycle-savepoints, read-phenomena-dirty-nonrepeatable-phantom, write-anomalies-lost-update-write-skew, read-uncommitted-read-committed\n *\n * Summary:\n *   A multi-session transaction schedule analyzer implementing Adya dependency serialization graphs (WW, WR, RW anti-dependencies), cycle detection for Dirty Read / Lost Update / Write Skew, and Wait-For Graph deadlock victim selection.\n *\n * Key Engineering Highlights:\n *   1. Adya Serialization Graph builder extracting WW, WR, and RW (anti-dependency) edges from interleaved schedules\n *   2. Automated classification of Lost Update (P4) vs Write Skew (A5B) under Snapshot Isolation\n *   3. Wait-For Graph cycle detection and minimum-cost deadlock victim abort selection\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Conflict Extraction (WW, WR, RW Anti-Dependencies): Implement `extractDependencies(schedule)` to scan an ordered list of `{ tx, op: \"R\"|\"W\", key }` events and emit `{ from, to, type: \"WW\"|\"WR\"|\"RW\", key }` conflict edges.\n *   - Step 2: Serialization Graph Cycle Detector: Implement `hasSerializationCycle(edges)` to return `true` if the transaction dependency graph contains a directed cycle (meaning the schedule is not conflict-serializable).\n *   - Step 3: Lost Update vs Write Skew Anomaly Classifier: Implement `classifyScheduleAnomaly(schedule)` to return `\"SERIALIZABLE\"`, `\"LOST_UPDATE\"`, or `\"WRITE_SKEW\"`.\n *   - Step 4: Lock Manager Wait-For Graph & Deadlock Victim Selector: Implement `selectDeadlockVictim(waitEdges, txWeights)` to detect a deadlock cycle and return the victim transaction ID with the lowest `txWeights[tx]`.\n * ============================================================================\n */\n\nclass ConcurrencyAnomalySimulator {\n  static extractDependencies(schedule) {\n    const edges = [];\n    for (let i = 0; i < schedule.length; i++) {\n      for (let j = i + 1; j < schedule.length; j++) {\n        const a = schedule[i], b = schedule[j];\n        if (a.tx === b.tx || a.key !== b.key) continue;\n        if (a.op === 'W' && b.op === 'W') edges.push({ from: a.tx, to: b.tx, type: 'WW', key: a.key });\n        else if (a.op === 'W' && b.op === 'R') edges.push({ from: a.tx, to: b.tx, type: 'WR', key: a.key });\n        else if (a.op === 'R' && b.op === 'W') edges.push({ from: a.tx, to: b.tx, type: 'RW', key: a.key });\n      }\n    }\n    return edges;\n  }\n\n  static hasSerializationCycle(edges) {\n    const adj = new Map();\n    for (const e of edges) {\n      if (!adj.has(e.from)) adj.set(e.from, new Set());\n      adj.get(e.from).add(e.to);\n    }\n    const state = new Map(); // 1 = visiting, 2 = visited\n    function dfs(u) {\n      state.set(u, 1);\n      for (const v of adj.get(u) || []) {\n        if (state.get(v) === 1) return true;\n        if (!state.get(v) && dfs(v)) return true;\n      }\n      state.set(u, 2);\n      return false;\n    }\n    for (const node of adj.keys()) {\n      if (!state.get(node) && dfs(node)) return true;\n    }\n    return false;\n  }\n\n  static classifyScheduleAnomaly(schedule) {\n    const edges = this.extractDependencies(schedule);\n    if (!this.hasSerializationCycle(edges)) return 'SERIALIZABLE';\n    const hasWW = edges.some(e => e.type === 'WW');\n    if (hasWW) return 'LOST_UPDATE';\n    const rwKeys = new Set(edges.filter(e => e.type === 'RW').map(e => e.key));\n    if (rwKeys.size >= 2) return 'WRITE_SKEW';\n    return 'NON_SERIALIZABLE';\n  }\n\n  static selectDeadlockVictim(waitEdges, txWeights) {\n    const adj = new Map();\n    for (const { waiter, holder } of waitEdges) {\n      if (!adj.has(waiter)) adj.set(waiter, []);\n      adj.get(waiter).push(holder);\n    }\n    const cycleNodes = new Set();\n    for (const start of adj.keys()) {\n      const visited = new Set();\n      let cur = start;\n      while (cur && !visited.has(cur)) {\n        visited.add(cur);\n        const nexts = adj.get(cur) || [];\n        cur = nexts[0] || null;\n        if (cur === start) {\n          for (const n of visited) cycleNodes.add(n);\n          break;\n        }\n      }\n    }\n    if (cycleNodes.size === 0) return null;\n    return Array.from(cycleNodes).sort((a, b) => (txWeights[a] || 0) - (txWeights[b] || 0))[0];\n  }\n}\n\nmodule.exports = { ConcurrencyAnomalySimulator };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  // Lost update: T1 reads X, T2 reads X, T1 writes X, T2 writes X\n  const lostUpdate = [\n    { tx: 'T1', op: 'R', key: 'acct_1' },\n    { tx: 'T2', op: 'R', key: 'acct_1' },\n    { tx: 'T1', op: 'W', key: 'acct_1' },\n    { tx: 'T2', op: 'W', key: 'acct_1' }\n  ];\n  assert.equal(ConcurrencyAnomalySimulator.classifyScheduleAnomaly(lostUpdate), 'LOST_UPDATE');\n\n  // Write skew: T1 reads doc_A & doc_B, T2 reads doc_A & doc_B, T1 writes doc_A, T2 writes doc_B\n  const writeSkew = [\n    { tx: 'T1', op: 'R', key: 'doc_A' },\n    { tx: 'T1', op: 'R', key: 'doc_B' },\n    { tx: 'T2', op: 'R', key: 'doc_A' },\n    { tx: 'T2', op: 'R', key: 'doc_B' },\n    { tx: 'T1', op: 'W', key: 'doc_A' },\n    { tx: 'T2', op: 'W', key: 'doc_B' }\n  ];\n  assert.equal(ConcurrencyAnomalySimulator.classifyScheduleAnomaly(writeSkew), 'WRITE_SKEW');\n\n  const victim = ConcurrencyAnomalySimulator.selectDeadlockVictim(\n    [{ waiter: 'T1', holder: 'T2' }, { waiter: 'T2', holder: 'T1' }],\n    { T1: 50, T2: 10 }\n  );\n  assert.equal(victim, 'T2');\n  return true;\n}\nrunTests();\n",
