    "code": "'use strict';\n/**\n * ============================================================================\n * Multi-Version Tuple Store with Snapshot Isolation & Vacuum GC (build-mvcc-snapshot-storage-engine)\n * ============================================================================\n * Category: MVCC, Locking & Deadlocks\n * Difficulty: Advanced (~45 min)\n * Primary Curriculum Unit: build-mvcc-snapshot-storage-engine\n * Related Units: multi-version-concurrency-control-mvcc, tuple-headers-xmin-xmax-visibility, transaction-snapshots-visibility-rules, row-level-locks-for-update-skip-locked, table-locks-intention-locks-ddl-hazards\n *\n * Summary:\n *   A PostgreSQL-style Multi-Version Concurrency Control (MVCC) storage engine implementing (xmin, xmax) tuple headers, Snapshot Isolation (xmin, xmax, xip_list) visibility rules, First-Committer-Wins write conflict detection, and VACUUM dead-tuple garbage collection.\n *\n * Key Engineering Highlights:\n *   1. PostgreSQL tuple header versioning (xmin, xmax) where UPDATE expires the old version and appends a new version\n *   2. Snapshot Isolation visibility evaluator over (xmin, xmax, xip_list) active transaction sets\n *   3. First-Committer-Wins write-write conflict detection and VACUUM dead-tuple reclamation below globalOldestXmin\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Transaction Allocation & Snapshot Capture (xmin, xmax, xip): Implement `beginTransaction()` to allocate a monotonically increasing `txid` and capture a snapshot `{ selfTx: txid, xmin, xmax: this.nextTxId, xip: new Set(activeOtherTxs) }`.\n *   - Step 2: Tuple Visibility Function (xmin / xmax / Commit State): Implement `isTupleVisible(tuple, snapshot)` so a tuple version is visible iff its creating transaction `xmin` is visible to `snapshot` and its deleting transaction `xmax` is either `null` or not visible to `snapshot`.\n *   - Step 3: Non-Overwriting UPDATE with First-Committer-Wins Conflict Detection: Implement `update(txid, key, newValue)` to detect concurrent write conflicts (`tuple.xmax !== null`) and append a new tuple version.\n *   - Step 4: VACUUM Dead Tuple Garbage Collector: Implement `vacuum()` to compute `globalOldestXmin` across all active transactions and purge dead tuple versions that no active or future transaction can ever see.\n * ============================================================================\n */\n\nclass MvccStorageEngine {\n  constructor() {\n    this.nextTxId = 100;\n    this.txStatus = new Map();\n    this.snapshots = new Map();\n    this.tuples = [];\n  }\n\n  beginTransaction() {\n    const txid = this.nextTxId++;\n    const active = [];\n    for (const [id, st] of this.txStatus.entries()) {\n      if (st === 'ACTIVE') active.push(id);\n    }\n    this.txStatus.set(txid, 'ACTIVE');\n    const xmin = active.length > 0 ? Math.min(...active, txid) : txid;\n    this.snapshots.set(txid, {\n      selfTx: txid,\n      xmin,\n      xmax: this.nextTxId,\n      xip: new Set(active)\n    });\n    return txid;\n  }\n\n  commit(txid) { this.txStatus.set(txid, 'COMMITTED'); }\n  abort(txid) { this.txStatus.set(txid, 'ABORTED'); }\n\n  insert(txid, key, value) {\n    this.tuples.push({ key, value, xmin: txid, xmax: null });\n  }\n\n  _txVisibleInSnapshot(targetTx, snap) {\n    if (targetTx === snap.selfTx) return true;\n    if (this.txStatus.get(targetTx) !== 'COMMITTED') return false;\n    if (targetTx >= snap.xmax) return false;\n    if (snap.xip.has(targetTx)) return false;\n    return true;\n  }\n\n  isTupleVisible(tuple, snapshot) {\n    if (!this._txVisibleInSnapshot(tuple.xmin, snapshot)) return false;\n    if (tuple.xmax === null) return true;\n    if (tuple.xmax === snapshot.selfTx) return false;\n    if (this._txVisibleInSnapshot(tuple.xmax, snapshot)) return false;\n    return true;\n  }\n\n  read(txid, key) {\n    const snap = this.snapshots.get(txid);\n    const found = this.tuples.find(t => t.key === key && this.isTupleVisible(t, snap));\n    return found ? found.value : undefined;\n  }\n\n  update(txid, key, newValue) {\n    const snap = this.snapshots.get(txid);\n    const cur = this.tuples.find(t => t.key === key && this.isTupleVisible(t, snap));\n    if (!cur) throw new Error('Key not found: ' + key);\n    if (cur.xmax !== null && this.txStatus.get(cur.xmax) !== 'ABORTED') {\n      throw new Error('First-Committer-Wins serialization conflict on key: ' + key);\n    }\n    cur.xmax = txid;\n    this.tuples.push({ key, value: newValue, xmin: txid, xmax: null });\n  }\n\n  vacuum() {\n    let globalOldestXmin = this.nextTxId;\n    for (const [id, st] of this.txStatus.entries()) {\n      if (st === 'ACTIVE') {\n        const snap = this.snapshots.get(id);\n        globalOldestXmin = Math.min(globalOldestXmin, id, snap ? snap.xmin : id);\n      }\n    }\n    const before = this.tuples.length;\n    this.tuples = this.tuples.filter(t => {\n      if (this.txStatus.get(t.xmin) === 'ABORTED') return false;\n      if (t.xmax !== null && this.txStatus.get(t.xmax) === 'COMMITTED' && t.xmax < globalOldestXmin) {\n        return false;\n      }\n      return true;\n    });\n    return before - this.tuples.length;\n  }\n}\n\nmodule.exports = { MvccStorageEngine };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const mvcc = new MvccStorageEngine();\n\n  const t1 = mvcc.beginTransaction();\n  mvcc.insert(t1, 'bal', 1000);\n  mvcc.commit(t1);\n\n  const tReader = mvcc.beginTransaction();\n  const tWriter = mvcc.beginTransaction();\n  mvcc.update(tWriter, 'bal', 1500);\n  mvcc.commit(tWriter);\n\n  // Snapshot Isolation: tReader still sees 1000 even after tWriter committed!\n  assert.equal(mvcc.read(tReader, 'bal'), 1000);\n  // First-Committer-Wins: tReader cannot overwrite 'bal' because tWriter modified it\n  assert.throws(() => mvcc.update(tReader, 'bal', 2000), /First-Committer-Wins/);\n  mvcc.commit(tReader);\n\n  const tNew = mvcc.beginTransaction();\n  assert.equal(mvcc.read(tNew, 'bal'), 1500);\n  mvcc.commit(tNew);\n\n  const reclaimed = mvcc.vacuum();\n  assert.equal(reclaimed, 1);\n  assert.equal(mvcc.tuples.length, 1);\n  return true;\n}\nrunTests();\n",
