    "code": "'use strict';\n/**\n * ============================================================================\n * 8KB Slotted Page + Write-Ahead Log Crash Recovery Simulator (build-slotted-page-wal-engine)\n * ============================================================================\n * Category: Storage Engines, Buffer Pool & WAL\n * Difficulty: Advanced (~45 min)\n * Primary Curriculum Unit: build-slotted-page-wal-engine\n * Related Units: slotted-page-layout-8kb-anatomy, heap-files-hot-updates-fillfactor, buffer-pool-clock-sweep-lru-k, write-ahead-logging-wal-lsn, checkpoints-dirty-page-flushing\n *\n * Summary:\n *   A disk-page storage engine implementing an 8KB slotted page with downward line-pointer array growth and upward tuple growth, PageLSN tracking, and 3-phase ARIES crash recovery (Analysis, Redo, Undo).\n *\n * Key Engineering Highlights:\n *   1. 8KB Slotted Page memory layout growing line pointers downward and variable-length tuples upward\n *   2. In-place line-pointer compaction reclaiming fragmented tuple space without changing external TIDs\n *   3. Three-phase ARIES WAL recovery (Analysis, Redo from minRecLSN, and reverse Undo with CLR logging)\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: 8KB Slotted Page Tuple Allocation (pd_lower & pd_upper): Implement `insertTuple(payloadStr, lsn)` to allocate space in an 8192-byte slotted page where header `pd_lower` grows downward by 4 bytes per slot and `pd_upper` grows upward by tuple byte length.\n *   - Step 2: Tuple Deletion & In-Place Page Compaction: Implement `deleteTuple(slotId, lsn)` and `compactPage()` so that dead tuple bytes are reclaimed and `pd_upper` is restored while every live tuple keeps its original `slotId`.\n *   - Step 3: ARIES WAL Analysis Phase (Active Tx Table & Dirty Page Table): Implement `analyzeWal(walRecords)` to identify uncommitted `loserTxs` and the minimum `redoStartLsn` across dirty pages.\n *   - Step 4: ARIES Redo (Repeating History) & Undo (Loser Rollback): Implement `recoverWal(walRecords, initialPages)` to execute ARIES Redo followed by reverse-LSN Undo of uncommitted loser transactions.\n * ============================================================================\n */\n\nclass SlottedPageWalEngine {\n  constructor(pageSize = 8192) {\n    this.pageSize = pageSize;\n    this.pd_lower = 24;\n    this.pd_upper = pageSize;\n    this.pageLsn = 0;\n    this.slots = [];\n  }\n\n  get freeSpace() { return this.pd_upper - this.pd_lower; }\n\n  insertTuple(payloadStr, lsn = 1) {\n    const len = payloadStr.length;\n    if (this.freeSpace < 4 + len) return -1;\n    this.pd_upper -= len;\n    this.pd_lower += 4;\n    this.pageLsn = Math.max(this.pageLsn, lsn);\n    const slotId = this.slots.length;\n    this.slots.push({ offset: this.pd_upper, length: len, data: payloadStr, dead: false });\n    return slotId;\n  }\n\n  deleteTuple(slotId, lsn = 1) {\n    const s = this.slots[slotId];\n    if (!s || s.dead) return false;\n    s.dead = true;\n    s.data = null;\n    this.pageLsn = Math.max(this.pageLsn, lsn);\n    return true;\n  }\n\n  compactPage() {\n    let cursor = this.pageSize;\n    for (const s of this.slots) {\n      if (!s.dead) {\n        cursor -= s.length;\n        s.offset = cursor;\n      }\n    }\n    this.pd_upper = cursor;\n  }\n\n  static analyzeWal(walRecords) {\n    const active = new Set();\n    let redoStartLsn = null;\n    for (const r of walRecords) {\n      if (r.type === 'BEGIN') active.add(r.tx);\n      else if (r.type === 'UPDATE') {\n        active.add(r.tx);\n        if (redoStartLsn === null || r.lsn < redoStartLsn) redoStartLsn = r.lsn;\n      } else if (r.type === 'COMMIT' || r.type === 'ABORT') {\n        active.delete(r.tx);\n      }\n    }\n    return { loserTxs: Array.from(active), redoStartLsn };\n  }\n\n  static recoverWal(walRecords, initialPages = {}) {\n    const pages = JSON.parse(JSON.stringify(initialPages));\n    const { loserTxs } = this.analyzeWal(walRecords);\n    const loserSet = new Set(loserTxs);\n\n    // Phase 2: Redo (Repeating History)\n    for (const r of walRecords) {\n      if (r.type === 'UPDATE') {\n        const p = pages[r.pageId] || { val: null, pageLsn: 0 };\n        if (p.pageLsn < r.lsn) {\n          p.val = r.after;\n          p.pageLsn = r.lsn;\n        }\n        pages[r.pageId] = p;\n      }\n    }\n\n    // Phase 3: Undo loser transactions in reverse LSN order\n    for (let i = walRecords.length - 1; i >= 0; i--) {\n      const r = walRecords[i];\n      if (r.type === 'UPDATE' && loserSet.has(r.tx)) {\n        pages[r.pageId].val = r.before;\n        pages[r.pageId].pageLsn += 1;\n      }\n    }\n    return pages;\n  }\n}\n\nmodule.exports = { SlottedPageWalEngine };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const page = new SlottedPageWalEngine(128);\n  const s0 = page.insertTuple('row_zero_payload', 10);\n  const s1 = page.insertTuple('row_one_payload_', 20);\n  const s2 = page.insertTuple('row_two_payload_', 30);\n  assert.equal(s0, 0);\n  assert.equal(s1, 1);\n  assert.equal(s2, 2);\n\n  const freeBefore = page.freeSpace;\n  page.deleteTuple(1, 40);\n  page.compactPage();\n  assert.equal(page.freeSpace, freeBefore + 16);\n  assert.equal(page.slots[2].data, 'row_two_payload_'); // slotId 2 preserved!\n\n  const wal = [\n    { lsn: 10, tx: 'T1', type: 'BEGIN' },\n    { lsn: 20, tx: 'T1', type: 'UPDATE', pageId: 'P1', before: 100, after: 250 },\n    { lsn: 30, tx: 'T2', type: 'BEGIN' },\n    { lsn: 40, tx: 'T2', type: 'UPDATE', pageId: 'P2', before: 500, after: 999 },\n    { lsn: 50, tx: 'T1', type: 'COMMIT' }\n  ];\n  const recovered = SlottedPageWalEngine.recoverWal(wal, {\n    P1: { val: 100, pageLsn: 0 },\n    P2: { val: 500, pageLsn: 0 }\n  });\n  assert.equal(recovered.P1.val, 250); // Winner T1 Redone\n  assert.equal(recovered.P2.val, 500); // Loser T2 Undone\n  return true;\n}\nrunTests();\n",
