    "code": "'use strict';\n/**\n * ============================================================================\n * Columnar RLE/Dictionary Encoder with Zone-Map Predicate Pushdown (build-columnar-compression-query-engine)\n * ============================================================================\n * Category: Columnar OLAP & Modern Engines\n * Difficulty: Advanced (~40 min)\n * Primary Curriculum Unit: build-columnar-compression-query-engine\n * Related Units: columnar-storage-layout-parquet, columnar-compression-rle-dictionary-delta, late-materialization-simd-vectorization, zone-maps-min-max-pruning-bloom, embedded-olap-duckdb-architecture\n *\n * Summary:\n *   A Parquet/DuckDB-style columnar execution engine implementing Dictionary + Run-Length Encoding (RLE), Row-Group Zone-Map (min/max) pruning, and late-materialization direct compressed predicate evaluation.\n *\n * Key Engineering Highlights:\n *   1. Dictionary + Run-Length Encoding (RLE) compressing sorted low-cardinality columns by 10x–50x\n *   2. Row-Group Zone-Map (min, max) metadata pruning skipping irrelevant row groups without decompression\n *   3. Direct predicate evaluation over RLE runs and late materialization of projected attributes\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Dictionary + Run-Length Encoding (RLE) Compressor: Implement `encodeDictionaryRle(values)` returning `{ dict, runs: [{ code, count }] }`.\n *   - Step 2: Row-Group Zone-Map (Min/Max) Builder: Implement `buildRowGroups(rows, groupSize, statCol)` to partition rows into fixed-size row groups annotated with `{ min, max, count, rows }`.\n *   - Step 3: Zone-Map Row-Group Pruning Scan: Implement `scanWithZoneMaps(rowGroups, statCol, minVal, maxVal)` to prune non-overlapping row groups before inspecting rows.\n *   - Step 4: Direct Compressed RLE Count Without Decompression: Implement `countCompressedEquals(encodedCol, targetVal)` to count matching tuples directly from the RLE runs in $O(\\text{runs})$ time without decompressing individual rows.\n * ============================================================================\n */\n\nclass ColumnarQueryEngine {\n  static encodeDictionaryRle(values) {\n    const dict = [];\n    const codeMap = new Map();\n    const runs = [];\n\n    for (const v of values) {\n      let code = codeMap.get(v);\n      if (code === undefined) {\n        code = dict.length;\n        dict.push(v);\n        codeMap.set(v, code);\n      }\n      if (runs.length > 0 && runs[runs.length - 1].code === code) {\n        runs[runs.length - 1].count++;\n      } else {\n        runs.push({ code, count: 1 });\n      }\n    }\n    return { dict, runs };\n  }\n\n  static buildRowGroups(rows, groupSize, statCol) {\n    const groups = [];\n    for (let i = 0; i < rows.length; i += groupSize) {\n      const chunk = rows.slice(i, i + groupSize);\n      const vals = chunk.map(r => r[statCol]);\n      groups.push({\n        min: Math.min(...vals),\n        max: Math.max(...vals),\n        rows: chunk\n      });\n    }\n    return groups;\n  }\n\n  static scanWithZoneMaps(rowGroups, statCol, minVal, maxVal) {\n    const matchedRows = [];\n    let groupsScanned = 0;\n    let groupsSkipped = 0;\n    for (const rg of rowGroups) {\n      if (rg.max < minVal || rg.min > maxVal) {\n        groupsSkipped++;\n        continue;\n      }\n      groupsScanned++;\n      for (const r of rg.rows) {\n        if (r[statCol] >= minVal && r[statCol] <= maxVal) matchedRows.push(r);\n      }\n    }\n    return { matchedRows, groupsScanned, groupsSkipped };\n  }\n\n  static countCompressedEquals(encodedCol, targetVal) {\n    const targetCode = encodedCol.dict.indexOf(targetVal);\n    if (targetCode === -1) return 0;\n    let total = 0;\n    for (const run of encodedCol.runs) {\n      if (run.code === targetCode) total += run.count;\n    }\n    return total;\n  }\n}\n\nmodule.exports = { ColumnarQueryEngine };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const col = ['US', 'US', 'US', 'EU', 'EU', 'US', 'APAC'];\n  const enc = ColumnarQueryEngine.encodeDictionaryRle(col);\n  assert.deepEqual(enc.dict, ['US', 'EU', 'APAC']);\n  assert.equal(enc.runs.length, 4);\n  assert.equal(ColumnarQueryEngine.countCompressedEquals(enc, 'US'), 4);\n  assert.equal(ColumnarQueryEngine.countCompressedEquals(enc, 'LATAM'), 0);\n\n  const rows = Array.from({ length: 12 }, (_, i) => ({ id: i + 1, ts: (i + 1) * 10 }));\n  const rgs = ColumnarQueryEngine.buildRowGroups(rows, 3, 'ts');\n  assert.equal(rgs.length, 4);\n\n  const scan = ColumnarQueryEngine.scanWithZoneMaps(rgs, 'ts', 75, 90);\n  assert.equal(scan.groupsSkipped, 3);\n  assert.equal(scan.groupsScanned, 1);\n  assert.deepEqual(scan.matchedRows.map(r => r.ts), [80, 90]);\n  return true;\n}\nrunTests();\n",
