    "code": "'use strict';\n/**\n * ============================================================================\n * Consistent-Hash Shard Router with Partition Pruning & Scatter-Gather (build-sharded-query-router)\n * ============================================================================\n * Category: Distributed SQL, Partitioning & Sharding\n * Difficulty: Advanced (~45 min)\n * Primary Curriculum Unit: build-sharded-query-router\n * Related Units: single-leader-replication-sync-async, read-replicas-consistency-models, failover-split-brain-fencing-tokens, declarative-table-partitioning, horizontal-sharding-routing-keys\n *\n * Summary:\n *   A distributed SQL proxy router implementing FNV-1a consistent hash ring routing, single-shard vs scatter-gather query planning, LSN-fenced read-your-writes replica selection, and distributed Top-K merge.\n *\n * Key Engineering Highlights:\n *   1. Deterministic FNV-1a virtual-node consistent hash ring routing tenant keys with minimal rebalancing movement\n *   2. Single-shard pruning when tenant_id is constrained vs parallel Scatter-Gather merge across shards\n *   3. Read-Your-Writes causal consistency router selecting replicas with replayLsn >= clientWriteLsn\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: FNV-1a Virtual-Node Consistent Hash Ring Routing: Implement `routeShardKey(shardKey)` to hash `shardKey` with FNV-1a and binary-search the sorted virtual-node ring, wrapping around to index `0` when `keyHash` exceeds the last ring token.\n *   - Step 2: Single-Shard Pruning vs Scatter-Gather Planner: Implement `planQuery(query)` to return `{ mode: \"SINGLE_SHARD\" | \"SCATTER_GATHER\", targetShards }`.\n *   - Step 3: Distributed Scatter-Gather Top-K Coordinator Merge: Implement `scatterGatherTopK(shardDataMap, sortCol, k)` to pull at most `k` pre-sorted tuples from each shard and merge them into the exact global top-$k$.\n *   - Step 4: LSN-Fenced Read-Your-Writes Replica Selector: Implement `selectReadNode(replicas, requiredLsn)` to select the lowest-latency replica whose `replayLsn >= requiredLsn`, falling back to `\"PRIMARY\"` when all replicas lag.\n * ============================================================================\n */\n\nfunction fnv1a32(str) {\n  const s = String(str);\n  let h = 0x811c9dc5;\n  for (let i = 0; i < s.length; i++) {\n    h ^= s.charCodeAt(i);\n    h = Math.imul(h, 0x01000193);\n  }\n  return h >>> 0;\n}\n\nclass ShardedQueryRouter {\n  constructor(shards = ['shard_0', 'shard_1', 'shard_2'], vnodes = 8) {\n    this.shards = shards;\n    this.ring = [];\n    for (const s of shards) {\n      for (let v = 0; v < vnodes; v++) {\n        this.ring.push({ hash: fnv1a32(`${s}#${v}`), shard: s });\n      }\n    }\n    this.ring.sort((a, b) => a.hash - b.hash);\n  }\n\n  routeShardKey(shardKey) {\n    const h = fnv1a32(shardKey);\n    for (const node of this.ring) {\n      if (node.hash >= h) return node.shard;\n    }\n    return this.ring[0].shard;\n  }\n\n  planQuery(query) {\n    if (query && query.shardKey !== undefined && query.shardKey !== null) {\n      return { mode: 'SINGLE_SHARD', targetShards: [this.routeShardKey(query.shardKey)] };\n    }\n    return { mode: 'SCATTER_GATHER', targetShards: this.shards.slice() };\n  }\n\n  scatterGatherTopK(shardDataMap, sortCol, k = 3) {\n    const candidates = [];\n    for (const shard of this.shards) {\n      const rows = (shardDataMap[shard] || [])\n        .slice()\n        .sort((a, b) => b[sortCol] - a[sortCol])\n        .slice(0, k);\n      candidates.push(...rows);\n    }\n    return candidates.sort((a, b) => b[sortCol] - a[sortCol]).slice(0, k);\n  }\n\n  static selectReadNode(replicas, requiredLsn) {\n    const eligible = replicas\n      .filter(r => r.replayLsn >= requiredLsn)\n      .sort((a, b) => a.latencyMs - b.latencyMs);\n    return eligible.length > 0 ? eligible[0].id : 'PRIMARY';\n  }\n}\n\nmodule.exports = { ShardedQueryRouter, fnv1a32 };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const router = new ShardedQueryRouter(['shard_0', 'shard_1', 'shard_2'], 16);\n\n  const single = router.planQuery({ shardKey: 'tenant_42' });\n  assert.equal(single.mode, 'SINGLE_SHARD');\n  assert.equal(single.targetShards.length, 1);\n\n  const scatter = router.planQuery({});\n  assert.equal(scatter.mode, 'SCATTER_GATHER');\n  assert.equal(scatter.targetShards.length, 3);\n\n  const top = router.scatterGatherTopK({\n    shard_0: [{ id: 1, rev: 500 }, { id: 2, rev: 100 }],\n    shard_1: [{ id: 3, rev: 900 }, { id: 4, rev: 300 }],\n    shard_2: [{ id: 5, rev: 700 }]\n  }, 'rev', 3);\n  assert.deepEqual(top.map(r => r.rev), [900, 700, 500]);\n\n  const replicas = [\n    { id: 'rep_1', replayLsn: 105, latencyMs: 2 },\n    { id: 'rep_2', replayLsn: 150, latencyMs: 6 }\n  ];\n  assert.equal(ShardedQueryRouter.selectReadNode(replicas, 120), 'rep_2');\n  assert.equal(ShardedQueryRouter.selectReadNode(replicas, 200), 'PRIMARY');\n  return true;\n}\nrunTests();\n",
