    "code": "'use strict';\n/**\n * ============================================================================\n * End-to-End Slow Query Diagnostic & Optimization Clinic (100x Speedup) (build-production-sql-tuning-clinic)\n * ============================================================================\n * Category: Production SQL Patterns & Tuning\n * Difficulty: Advanced (~45 min)\n * Primary Curriculum Unit: build-production-sql-tuning-clinic\n * Related Units: keyset-cursor-pagination-vs-offset, solving-n-plus-one-orm-queries, full-text-search-trigrams-inverted-index, queue-processing-skip-locked-patterns, bulk-ingestion-batching-unlogged-tables\n *\n * Summary:\n *   A production SQL performance engineering toolkit implementing O(1) keyset seek pagination, N+1 query batching coalescer, lock-free FOR UPDATE SKIP LOCKED worker queues, and chunked primary-key backfills.\n *\n * Key Engineering Highlights:\n *   1. Keyset seek cursor pagination (created_at, id) < (cursor_ts, cursor_id) running in constant O(log N) time\n *   2. DataLoader-style N+1 query batching coalescer collapsing K loop queries into 1 bulk ANY($1) lookup\n *   3. Lock-free concurrent worker queue claiming via FOR UPDATE SKIP LOCKED with visibility timeout recovery\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Deterministic Keyset Cursor Pagination ((ts, id) < (cursorTs, cursorId)): Implement `keysetPaginateDesc(rows, cursor, pageSize)` to return `{ items, nextCursor }` ordered by `(ts DESC, id DESC)` using strict composite tuple comparison.\n *   - Step 2: N+1 Query Batch Coalescer: Implement `batchLoadChildren(parents, childTable, fkCol)` to hydrate every parent with its `children` array in a single batched pass, returning `{ enrichedParents, queryCount: 1 }`.\n *   - Step 3: Lock-Free FOR UPDATE SKIP LOCKED Job Queue Claimer: Implement `claimNextJobsSkipLocked(jobs, lockedIds, workerId, batchSize)` to claim up to `batchSize` unlocked pending jobs ordered by `id ASC`.\n *   - Step 4: Key-Range Chunked Batch Backfill Planner: Implement `planChunkedBackfill(primaryKeys, batchSize)` to partition primary keys into bounded `{ minId, maxId, count }` ranges for zero-downtime migration.\n * ============================================================================\n */\n\nclass ProductionSqlTuningClinic {\n  static keysetPaginateDesc(rows, cursor = null, pageSize = 3) {\n    const sorted = rows.slice().sort((a, b) => (b.ts !== a.ts ? b.ts - a.ts : b.id - a.id));\n    const filtered = cursor\n      ? sorted.filter(r => r.ts < cursor.ts || (r.ts === cursor.ts && r.id < cursor.id))\n      : sorted;\n    const items = filtered.slice(0, pageSize);\n    const last = items[items.length - 1];\n    const nextCursor = items.length === pageSize && last ? { ts: last.ts, id: last.id } : null;\n    return { items, nextCursor };\n  }\n\n  static batchLoadChildren(parents, childTable, fkCol) {\n    const parentIds = new Set(parents.map(p => p.id));\n    const byParent = new Map();\n    for (const id of parentIds) byParent.set(id, []);\n    for (const c of childTable) {\n      if (parentIds.has(c[fkCol])) {\n        byParent.get(c[fkCol]).push(c);\n      }\n    }\n    const enrichedParents = parents.map(p => ({ ...p, children: byParent.get(p.id) || [] }));\n    return { enrichedParents, queryCount: 1 };\n  }\n\n  static claimNextJobsSkipLocked(jobs, lockedIds, workerId, batchSize = 2) {\n    const claimed = [];\n    const sorted = jobs.slice().sort((a, b) => a.id - b.id);\n    for (const job of sorted) {\n      if (claimed.length >= batchSize) break;\n      if (job.status === 'pending' && !lockedIds.has(job.id)) {\n        lockedIds.add(job.id);\n        job.status = 'processing';\n        job.workerId = workerId;\n        claimed.push(job);\n      }\n    }\n    return claimed;\n  }\n\n  static planChunkedBackfill(primaryKeys, batchSize = 1000) {\n    const sorted = primaryKeys.slice().sort((a, b) => a - b);\n    const batches = [];\n    for (let i = 0; i < sorted.length; i += batchSize) {\n      const chunk = sorted.slice(i, i + batchSize);\n      batches.push({\n        minId: chunk[0],\n        maxId: chunk[chunk.length - 1],\n        count: chunk.length\n      });\n    }\n    return batches;\n  }\n}\n\nmodule.exports = { ProductionSqlTuningClinic };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const feed = [\n    { id: 10, ts: 100 },\n    { id: 9, ts: 100 }, // tie on ts=100!\n    { id: 8, ts: 90 },\n    { id: 7, ts: 80 }\n  ];\n  const p1 = ProductionSqlTuningClinic.keysetPaginateDesc(feed, null, 2);\n  assert.deepEqual(p1.items.map(r => r.id), [10, 9]);\n  const p2 = ProductionSqlTuningClinic.keysetPaginateDesc(feed, p1.nextCursor, 2);\n  assert.deepEqual(p2.items.map(r => r.id), [8, 7]);\n\n  const batched = ProductionSqlTuningClinic.batchLoadChildren(\n    [{ id: 1 }, { id: 2 }],\n    [{ id: 100, user_id: 1 }, { id: 101, user_id: 1 }],\n    'user_id'\n  );\n  assert.equal(batched.queryCount, 1);\n  assert.equal(batched.enrichedParents[0].children.length, 2);\n  assert.equal(batched.enrichedParents[1].children.length, 0);\n\n  const jobs = [\n    { id: 1, status: 'pending' },\n    { id: 2, status: 'pending' },\n    { id: 3, status: 'pending' }\n  ];\n  const locks = new Set([1]); // job 1 already locked by another worker\n  const claimed = ProductionSqlTuningClinic.claimNextJobsSkipLocked(jobs, locks, 'w_2', 2);\n  assert.deepEqual(claimed.map(j => j.id), [2, 3]);\n\n  const chunks = ProductionSqlTuningClinic.planChunkedBackfill([1, 2, 5, 8, 12], 2);\n  assert.equal(chunks.length, 3);\n  assert.deepEqual(chunks[0], { minId: 1, maxId: 2, count: 2 });\n  return true;\n}\nrunTests();\n",
